-- Function: public.fn_get_unread_parent_communications_count
-- Backup generated on 2026-10-25 20:33:44

CREATE OR REPLACE FUNCTION public.fn_get_unread_parent_communications_count(p_tenant_id uuid, p_organization_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_classroom_id uuid DEFAULT NULL::uuid)  RETURNS bigint  LANGUAGE sql  STABLE AS $function$     SELECT COUNT(*)     FROM parent_communications pc     LEFT JOIN classrooms cl ON pc.classroom_id = cl.id     WHERE pc.tenant_id = p_tenant_id       AND pc.teacher_id = '00000000-0000-0000-0000-000000000000'       AND pc.delivery_status != 'Read'       AND (p_organization_id IS NULL OR pc.organization_id = p_organization_id)       AND (p_branch_id IS NULL OR cl.branch_id = p_branch_id)       AND (p_classroom_id IS NULL OR pc.classroom_id = p_classroom_id); $function$ ;
